INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (9581, 'Danh sách kiểm tra Kế hoạch kế nhiệm', 'danh-sach-kiem-tra-ke-hoach-ke-nhiem', '		<div data-elementor-type="wp-post" data-elementor-id="9581" class="elementor elementor-9581" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-9c4cb28 e-con-full e-flex e-con e-parent" data-id="9c4cb28" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-a4e705a e-con-full e-flex e-con e-parent" data-id="a4e705a" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-80a7597 e-con-full e-flex e-con e-parent" data-id="80a7597" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
