		<div class="elementor-element elementor-element-ffc7572 e-con-full e-flex e-con e-parent" data-id="ffc7572" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-8c4184d e-flex e-con-boxed e-con e-parent" data-id="8c4184d" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
