INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (9540, 'Mẫu phát triển cá nhân trong doanh nghiệp', 'mau-phat-trien-ca-nhan-trong-doanh-nghiep', '		<div data-elementor-type="wp-post" data-elementor-id="9540" class="elementor elementor-9540" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-1c676d7 e-con-full e-flex e-con e-parent" data-id="1c676d7" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-e9ae011 e-con-full e-flex e-con e-parent" data-id="e9ae011" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-619de12 e-con-full e-flex e-con e-parent" data-id="619de12" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
